// Kører på serveren, aldrig i browseren.
// Adgangsnøglen ligger i en miljøvariabel.
export async function onOrderCreated(req) {
  verifyShopifyHmac(req, process.env.SHOPIFY_WEBHOOK_SECRET);
  const order = await req.json();
  await erp.createOrder({
    reference: order.name,
    lines: order.line_items.map(toErpLine),
  });
}
